# Generated by manage.py generate_test_cases.
import json
from datetime import date

from django.contrib.contenttypes.models import ContentType

from bloomerp.automation.flows.object_if_condition import (
    ObjectIfConditionExecutor,
    ObjectIfConditionForm,
)
from bloomerp.automation.results import RouteResult
from bloomerp.automation.triggers.object_crud_trigger import ObjectCrudTrigger
from bloomerp.models.project_management.todo import Todo
from bloomerp.tests.base import (
    BloomerpWorkflowNodeTestCase,
    WorkflowNodeScenario,
)


class TestObjectIfConditionNode(BloomerpWorkflowNodeTestCase):
    node_id = 'OBJECT_IF_CONDITION'
    executor_class = ObjectIfConditionExecutor

    def test_condition_ports_allow_fanout(self) -> None:
        """
        Use case: Multiple workflow branches connect to either condition output.
        Expected result: Both ports permit unlimited connections.
        """
        # 1. Read the declared output ports.
        ports = {port.id: port for port in self.executor_class.get_output_ports()}

        # 2. Check each branch can fan out.
        self.assertIsNone(ports["true"].max_connections)
        self.assertIsNone(ports["false"].max_connections)

    def test_filter_form_saves_and_restores_groups(self) -> None:
        """
        Use case: A workflow editor submits grouped filter JSON.
        Expected result: The form saves groups and restores the scoped widget.
        """
        # 1. Submit the same JSON payload that FilterWidget emits.
        content_type = ContentType.objects.get_for_model(Todo)
        groups = [{"connector": "AND", "conditions": [
            {"field_path": "title", "lookup_id": "equals", "value": "Selected"},
        ]}]
        form = ObjectIfConditionForm(data={
            "content_type_id": str(content_type.pk),
            "filters": json.dumps(groups),
        })

        # 2. Verify the stored value and restored model scope.
        self.assertTrue(form.is_valid(), form.errors)
        self.assertEqual(form.cleaned_data["filters"], groups)
        restored = ObjectIfConditionForm(initial=form.cleaned_data)
        widget = restored.fields["filters"].widget
        self.assertEqual(widget.content_type_id, content_type.pk)
        self.assertTrue(widget.include_controls)
        self.assertEqual(json.loads(widget.format_value(restored.initial["filters"])), groups)

    def get_test_scenarios(self) -> list[WorkflowNodeScenario]:
        """Exercise direct and CRUD trigger inputs with grouped filters."""
        due_date = date(2026, 9, 24)
        todo = Todo.objects.create(title="Condition subject", required_by=due_date)
        other = Todo.objects.create(title="Another subject")
        content_type = ContentType.objects.get_for_model(Todo)
        input_data = {"id": str(todo.pk), "title": todo.title}
        other_data = {"id": str(other.pk), "title": other.title}
        matching_groups = [{"connector": "OR", "conditions": [
            {"field_path": "title", "lookup_id": "equals", "value": "No match"},
            {"field_path": "title", "lookup_id": "equals", "value": todo.title},
        ]}]
        trigger_input = ObjectCrudTrigger({}).execute({"instance": todo, "event": "created"})
        trigger_schema = ObjectCrudTrigger.get_output_schema({"content_type_id": content_type.pk})

        return [
            WorkflowNodeScenario(
                name="matching object in an OR filter routes true",
                parameters={
                    "content_type_id": content_type.pk,
                    "filters": matching_groups,
                },
                trigger_data=input_data,
                expected_output=RouteResult(port_id="true", output=input_data),
            ),
            WorkflowNodeScenario(
                name="object outside the filtered queryset routes false",
                parameters={
                    "content_type_id": content_type.pk,
                    "filters": json.dumps(matching_groups),
                },
                trigger_data=other_data,
                expected_output=RouteResult(port_id="false", output=other_data),
            ),
            WorkflowNodeScenario(
                name="resolved date value matches without JSON encoding",
                parameters={
                    "content_type_id": content_type.pk,
                    "filters": [{"connector": "AND", "conditions": [
                        {"field_path": "required_by", "lookup_id": "equals", "value": "{{ input.due_date }}"},
                    ]}],
                },
                trigger_data={"id": str(todo.pk), "due_date": due_date},
                expected_output=RouteResult(
                    port_id="true",
                    output={"id": str(todo.pk), "due_date": due_date},
                ),
            ),
            WorkflowNodeScenario(
                name="CRUD trigger instance matches and its schema is accepted",
                parameters={
                    "content_type_id": content_type.pk,
                    "filters": matching_groups,
                },
                trigger_data=trigger_input,
                expected_output=RouteResult(port_id="true", output=trigger_input),
                input_schema=trigger_schema,
                output_schema_validators=ObjectIfConditionExecutor.accepts_input_schema,
            ),
        ]
